"""An append-only page store with an in-memory ordered directory."""

from __future__ import annotations

import json
import os
from pathlib import Path

__all__ = ["PageStore"]

PAGE_SIZE = 4096
LOG_FILE = "pages.dat"


class PageStore:
    """A single-process page store rooted at ``root``."""

    def __init__(self, root: str | Path) -> None:
        self.directory = Path(root)
        self.path = self.directory / LOG_FILE

    def init(self) -> None:
        self.directory.mkdir(parents=True, exist_ok=True)
        self.path.write_bytes(b"")

    def _append(self, record: dict) -> int:
        payload = json.dumps(record, sort_keys=True).encode("utf-8")
        if len(payload) > PAGE_SIZE:
            raise ValueError(f"record exceeds one page ({len(payload)} > {PAGE_SIZE})")
        with self.path.open("ab") as handle:
            handle.write(len(payload).to_bytes(4, "big") + payload)
            handle.flush()
            os.fsync(handle.fileno())
        return sum(1 for _ in self._records()) 

    def _records(self) -> list[dict]:
        if not self.path.is_file():
            raise FileNotFoundError(f"no store at {self.path}; run init first")
        data, offset, out = self.path.read_bytes(), 0, []
        while offset + 4 <= len(data):
            size = int.from_bytes(data[offset:offset + 4], "big")
            chunk = data[offset + 4:offset + 4 + size]
            if len(chunk) < size:
                break  # a half-written tail record is discarded
            out.append(json.loads(chunk.decode("utf-8")))
            offset += 4 + size
        return out

    def put(self, key: str, value: str) -> int:
        if not key:
            raise ValueError("key must be non-empty")
        return self._append({"op": "put", "key": key, "value": value})

    def delete(self, key: str) -> int:
        return self._append({"op": "delete", "key": key})

    def _live(self) -> dict[str, str]:
        live: dict[str, str] = {}
        for record in self._records():
            if record["op"] == "put":
                live[record["key"]] = record["value"]
            else:
                live.pop(record["key"], None)
        return live

    def get(self, key: str) -> str | None:
        return self._live().get(key)

    def scan(self, start: str | None = None, end: str | None = None) -> list[tuple[str, str]]:
        items = sorted(self._live().items())
        return [(k, v) for k, v in items if (start is None or k >= start) and (end is None or k < end)]

    def recover(self) -> dict:
        """Reopen the page file, dropping a half-written tail record.

        Records are scanned strictly along length-prefix boundaries.  The first
        boundary that is not a whole, parseable record marks a half-written
        tail: scanning stops and every byte from that boundary on is removed, so
        later appends continue right after the last confirmed record.

        If a complete record can still be re-synchronised past the stop offset,
        the damage is mid-file corruption rather than a half-written tail:
        ``RuntimeError("corrupt_middle")`` is raised and the file is left
        byte-for-byte untouched.
        """
        if not self.directory.is_dir() or not self.path.is_file():
            raise FileNotFoundError(f"no store at {self.path}; run init first")
        data = self.path.read_bytes()
        size = len(data)
        offset, records = 0, 0
        while offset < size:
            record = self._record_at(data, offset)
            if record is None:
                break  # partial prefix, declared length past EOF, or bad payload
            offset = record["end"]
            records += 1
        truncated = offset < size
        if truncated:
            if self._has_record_after(data, offset):
                raise RuntimeError("corrupt_middle")
            with self.path.open("r+b") as handle:
                handle.truncate(offset)
                handle.flush()
                os.fsync(handle.fileno())
        return {"pages": (offset + PAGE_SIZE - 1) // PAGE_SIZE,
                "records": records, "truncated": truncated}

    def stats(self) -> dict:
        live = self._live()
        return {"pages": (self.path.stat().st_size + PAGE_SIZE - 1) // PAGE_SIZE if self.path.is_file() else 0,
                "records": len(self._records()), "keys": len(live)}

    @staticmethod
    def _record_at(data: bytes, offset: int) -> dict | None:
        """Parse one record at ``offset``; ``None`` when it is not whole and valid."""
        size = len(data)
        if offset + 4 > size:
            return None
        rec_size = int.from_bytes(data[offset:offset + 4], "big")
        if offset + 4 + rec_size > size:
            return None
        try:
            json.loads(data[offset + 4:offset + 4 + rec_size].decode("utf-8"))
        except (UnicodeDecodeError, ValueError):
            return None
        return {"end": offset + 4 + rec_size}

    def _has_record_after(self, data: bytes, offset: int) -> bool:
        """Whether any valid record can be re-synchronised past ``offset``."""
        return any(self._record_at(data, start) is not None
                   for start in range(offset + 1, len(data) - 3))

    def verify(self) -> dict:
        """Read-only check of the page file; never mutates the store."""
        result = {"status": "ok", "complete_records": 0, "valid_pages": 0,
                  "first_error_offset": None, "tail_partial_bytes": 0,
                  "scanned_end_offset": None, "error": None}
        if not self.directory.is_dir() or not self.path.is_file():
            result.update(status="error", error="invalid_path")
            return result
        try:
            data = self.path.read_bytes()
        except OSError:
            result.update(status="error", error="read_error")
            return result
        size = len(data)
        result["scanned_end_offset"] = size
        offset = 0
        while offset < size:
            record = self._record_at(data, offset)
            if record is None:
                break
            offset = record["end"]
            result["complete_records"] += 1
        result["valid_pages"] = offset // PAGE_SIZE
        if offset == size:
            return result
        if self._has_record_after(data, offset):
            result.update(status="corrupt_middle", error="corrupt_middle",
                          first_error_offset=offset)
        else:
            result.update(status="incomplete_tail", tail_partial_bytes=size - offset)
        return result

"""Command line entry point: ``python3 -m page_store --root <dir> <subcommand>``.

Exit codes: 0 success, 1 a storage or verification error, 2 a usage error.
The read-only ``verify`` subcommand additionally uses 3 when the page file
cannot be read and 4 when records follow a corrupt region.
"""

from __future__ import annotations

import argparse
import json
import sys

from . import DOMAIN, SOURCE_CATEGORIES, __version__
from .core import PageStore

USAGE_ERROR = 2

def _tags() -> list[str]:
    """Tags this domain claims: the comma-separated line that follows each named category heading."""
    import pathlib
    corpus = pathlib.Path(__file__).resolve().parent.parent / "corpus.md"
    if not corpus.is_file():
        return []
    wanted, tags, collect = set(SOURCE_CATEGORIES), [], False
    for line in corpus.read_text(encoding="utf-8").splitlines():
        stripped = line.strip()
        if stripped in wanted:
            collect = True
            continue
        if not collect or not stripped:
            continue
        for token in stripped.split(","):
            token = token.strip().replace("\\", "")
            if token and token not in tags:
                tags.append(token)
        collect = False
    return tags


def _report(component_names: list[str], readiness: dict[str, bool]) -> str:
    import json
    return json.dumps({"domain": DOMAIN, "version": __version__, "sourceCategories": list(SOURCE_CATEGORIES),
                       "tags": _tags(), "components": component_names, "readiness": readiness},
                      ensure_ascii=False, sort_keys=True)


def _parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="page_store", description="追加页存储与崩溃恢复")
    parser.add_argument("--root", required=True, help="working directory")
    sub = parser.add_subparsers(dest="command", required=True)
    sub.add_parser("init", help="create an empty store")
    put = sub.add_parser("put"); put.add_argument("key"); put.add_argument("value")
    get = sub.add_parser("get"); get.add_argument("key")
    delete = sub.add_parser("delete"); delete.add_argument("key")
    scan = sub.add_parser("scan"); scan.add_argument("--start"); scan.add_argument("--end")
    sub.add_parser("recover", help="reopen the page file")
    sub.add_parser("stats", help="print page, record and key counts")
    sub.add_parser("report", help="print this domain's report as JSON")
    sub.add_parser("verify", help="verify the page file read-only")
    return parser


def main(argv: list[str] | None = None) -> int:
    args = _parser().parse_args(argv)
    store = PageStore(args.root)
    try:
        if args.command == "init":
            store.init(); print(f"initialised {store.path}")
        elif args.command == "put":
            print(store.put(args.key, args.value))
        elif args.command == "get":
            value = store.get(args.key); print("" if value is None else value)
        elif args.command == "delete":
            print(store.delete(args.key))
        elif args.command == "scan":
            print(json.dumps(store.scan(args.start, args.end), ensure_ascii=False))
        elif args.command == "recover":
            try:
                print(json.dumps(store.recover(), sort_keys=True))
            except RuntimeError as error:
                if str(error) != "corrupt_middle":
                    raise
                offset = store.verify()["first_error_offset"]
                print(f"error: corrupt_middle at offset {offset}", file=sys.stderr)
                return 1
        elif args.command == "stats":
            print(json.dumps(store.stats(), sort_keys=True))
        elif args.command == "report":
            print(_report(["pages", "directory"], {"append": True, "recover": True, "compaction": False, "snapshotRead": False}))
        elif args.command == "verify":
            outcome = store.verify()
            print(json.dumps(outcome, sort_keys=True))
            if outcome["status"] == "error":
                print(f"error: {outcome['error']}: {store.path}", file=sys.stderr)
                return USAGE_ERROR if outcome["error"] == "invalid_path" else 3
            if outcome["status"] == "corrupt_middle":
                print(f"error: corrupt record at offset {outcome['first_error_offset']}", file=sys.stderr)
                return 4
        return 0
    except FileNotFoundError as error:
        print(f"error: {error}", file=sys.stderr)
        return 1
    except (KeyError, ValueError) as error:
        print(f"error: {error}", file=sys.stderr)
        return USAGE_ERROR


if __name__ == "__main__":
    raise SystemExit(main())

